import{_ as e,o as d,c as r,ag as i}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"11.2 软件工程高频词 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/02-软件工程高频词.md","filePath":"11-专业英语/02-软件工程高频词.md"}'),a={name:"11-专业英语/02-软件工程高频词.md"};function n(o,t,s,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_11-2-软件工程高频词-★★★" tabindex="-1">11.2 软件工程高频词 ★★★ <a class="header-anchor" href="#_11-2-软件工程高频词-★★★" aria-label="Permalink to &quot;11.2 软件工程高频词 ★★★&quot;">​</a></h1><h3 id="_2-1-开发过程与需求" tabindex="-1">2.1 开发过程与需求 <a class="header-anchor" href="#_2-1-开发过程与需求" aria-label="Permalink to &quot;2.1 开发过程与需求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>常见搭配/辨析</th></tr></thead><tbody><tr><td>requirement</td><td>需求</td><td>functional/non-functional requirement</td></tr><tr><td>requirements elicitation</td><td>需求获取</td><td>elicit requirements from stakeholders</td></tr><tr><td>stakeholder</td><td>利益相关者</td><td>用户、客户、管理者等</td></tr><tr><td>specification</td><td>规格说明</td><td>requirements specification</td></tr><tr><td>feasible / feasibility</td><td>可行的 / 可行性</td><td>feasibility study</td></tr><tr><td>lifecycle</td><td>生命周期</td><td>software development lifecycle, SDLC</td></tr><tr><td>iteration / increment</td><td>迭代 / 增量</td><td>iterative and incremental development</td></tr><tr><td>prototype</td><td>原型</td><td>clarify unclear requirements</td></tr><tr><td>deliverable</td><td>可交付成果</td><td>each phase produces deliverables</td></tr><tr><td>traceability</td><td>可追踪性</td><td>trace requirements to test cases</td></tr><tr><td>baseline</td><td>基线</td><td>approved baseline</td></tr><tr><td>configuration management</td><td>配置管理</td><td>control versions and changes</td></tr></tbody></table><p>必背句：</p><ul><li>A prototype helps users <strong>clarify requirements</strong>. 原型帮助用户明确需求。</li><li>Traceability links requirements <strong>to</strong> design elements and test cases. 可追踪性把需求与设计、测试用例关联起来。</li><li>The spiral model emphasizes <strong>risk analysis</strong>. 螺旋模型强调风险分析。</li><li>Agile development welcomes changing requirements and delivers software in short <strong>iterations</strong>. 敏捷开发接纳需求变化，以短迭代交付。</li></ul><h3 id="_2-2-设计与质量" tabindex="-1">2.2 设计与质量 <a class="header-anchor" href="#_2-2-设计与质量" aria-label="Permalink to &quot;2.2 设计与质量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>一眼识别</th></tr></thead><tbody><tr><td>cohesion</td><td>内聚</td><td>within a module</td></tr><tr><td>coupling</td><td>耦合</td><td>between modules</td></tr><tr><td>maintainability</td><td>可维护性</td><td>easy to analyze/change/test</td></tr><tr><td>reliability</td><td>可靠性</td><td>failure-free operation</td></tr><tr><td>availability</td><td>可用性</td><td>ready for use when needed</td></tr><tr><td>usability</td><td>易用性</td><td>easy to learn and operate</td></tr><tr><td>portability</td><td>可移植性</td><td>move across environments</td></tr><tr><td>scalability</td><td>可伸缩性</td><td>handle growing workload</td></tr><tr><td>reusability</td><td>可复用性</td><td>reuse components</td></tr><tr><td>modularity</td><td>模块化</td><td>divide into manageable modules</td></tr></tbody></table><p>高频结论：Good design aims for <strong>high cohesion and low coupling</strong>（高内聚、低耦合）。</p><p><strong>易错反例</strong>：<code>availability</code> 在系统质量中不是普通的“有没有货”，而是“系统需要时可用的概率/能力”；<code>reliability</code> 强调一段时间内无故障运行。系统可能很可靠但修复极慢，长期可用性仍受影响。</p><h3 id="_2-3-测试与维护" tabindex="-1">2.3 测试与维护 <a class="header-anchor" href="#_2-3-测试与维护" aria-label="Permalink to &quot;2.3 测试与维护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th></tr></thead><tbody><tr><td>verification</td><td>验证：产品是否按规格正确构建（Are we building the product right?）</td></tr><tr><td>validation</td><td>确认：产品是否满足用户真正需要（Are we building the right product?）</td></tr><tr><td>unit testing</td><td>单元测试</td></tr><tr><td>integration testing</td><td>集成测试</td></tr><tr><td>system testing</td><td>系统测试</td></tr><tr><td>acceptance testing</td><td>验收测试</td></tr><tr><td>regression testing</td><td>回归测试</td></tr><tr><td>test case / test suite</td><td>测试用例 / 测试套件</td></tr><tr><td>defect / fault / bug</td><td>缺陷、故障、错误</td></tr><tr><td>debugging</td><td>调试、定位并修复缺陷</td></tr><tr><td>corrective maintenance</td><td>改正性维护</td></tr><tr><td>adaptive maintenance</td><td>适应性维护</td></tr><tr><td>perfective maintenance</td><td>完善性维护</td></tr><tr><td>preventive maintenance</td><td>预防性维护</td></tr></tbody></table><p><strong>反例</strong>：testing 和 debugging 不是同义词。Testing 的目标是<strong>发现缺陷</strong>，debugging 的目标是<strong>定位原因并修复缺陷</strong>。</p><p><strong>应试动作</strong>：软件工程词先背三组：<code>requirement–stakeholder–traceability</code>；<code>cohesion–coupling–maintainability</code>；<code>verification–validation–regression testing</code>。看到英文定义时先回忆对应中文考点，再选词。</p><hr>',14)])])}const m=e(a,[["render",n]]);export{u as __pageData,m as default};
